import sys
OUT = sys.argv[1]
ROWS = [
 ("1", "Титул", "0:00", "", "Привітатись. Тема: подорож Україною за керамікою. ❓ Хто ліпив з глини?"),
 ("2", "Що таке кераміка", "2:00", "", "❓ Що у вас удома з глини? · глина + вогонь · після випалу не розмокає"),
 ("3", "Гіпсова форма", "4:30", "✋ форма + піала", "❓ Чому з гіпсу? · гіпс тягне воду · шар глини біля стінок · виріб зменшується й виходить"),
 ("4", "Крапля: три зразки", "7:00", "✋ вода", "❓ Що буде з краплею? · вазон — вбирає (пористий) · печатка 1250° — не вбирає · піала — скочується (глазур = скло)"),
 ("5", "Колись і тепер", "8:00", "", "❓ Як зробити глечик? · ліплення, круг, гіпс · дрова → газ, електропіч"),
 ("6", "Запитання до залу", "9:00", "📄 роздати аркуші", "❓ Яку кераміку знаєте? З якого краю? · названий край — відкрити"),
 ("7", "Карта 9 країв", "9:30", "", "9 «почерків»: глина, кольори, візерунки · із заходу на схід і до моря"),
 ("8", "⚡ Закарпаття", "10:00", "", "Вільхівка: темне тло, птахи й квіти, «Смерічка»"),
 ("9", "⭐ Гуцульщина", "12:00", "", "❓ Як отримують кольори? · білий ангоб · ритування · червінь · мідь = зелений, залізо = жовтий · полива · ЮНЕСКО"),
 ("10", "⚡ Галичина", "12:30", "", "❓ Чому глек чорний? · дим наприкінці випалу · кахлі Львова й Потелича"),
 ("11", "⭐ Поділля", "13:30", "", "❓ Бубнівка чи Бар? · червоний посуд, «пір'ячко» · Бар — біле тло, Бона Сфорца"),
 ("12", "⭐ Київщина", "14:30", "", "❓ Навіщо посудина з двома «трубами»? · Трипілля — понад 5000 років · спіралі"),
 ("13", "⚡ Полісся", "15:00", "", "Олешня, Ічня: прості задимлені горщики, лощіння"),
 ("14", "⭐ Полтавщина", "16:30", "", "❓ Хто знає, що таке куманець? · «бублик» з горлечком · Опішня — гончарна столиця"),
 ("15", "⚡ Слобожанщина", "17:00", "", "❓ Навіщо молоко? · молочена кераміка: коричнева, міцніша"),
 ("16", "⚡ Причорномор'я", "17:30", "", "❓ Чому гостре дно? · амфори Ольвії, Тіри, Херсонеса"),
 ("17–21", "Вікторина (5)", "19:30", "", "Учасники називають край — тикнути на карті. Мало часу → після 3-го до підсумку"),
 ("22", "Підсумок", "20:00", "", "❓ Що одне запам'ятали? · кожен виріб — «паспорт» краю"),
 ("23", "Бонус: СКОБ", "—", "📱", "Лише якщо є час: «▶ Почати гру», 6 інших фото на телефонах"),
]
QZ = [("Музей-заповідник гончарства", "Полтавщина (Опішня)"), ("Село, за яким названа Трипільська культура", "Київщина"),
      ("Грецькі міста з амфорами", "Причорномор'я"), ("Косівська мальована кераміка", "Гуцульщина"), ("Олешня, задимлені горщики", "Полісся")]
