rows = ''.join(f'<tr class="{"m" if "⭐" in r[1] else "s" if "⚡" in r[1] else ""}"><td>{r[0]}</td><td><b>{r[1]}</b></td><td class="t">{r[2]}</td><td>{r[3]}</td><td>{r[4]}</td></tr>' for r in ROWS)
qz = ''.join(f'<li>{q} — <b>{a}</b></li>' for q, a in QZ)
html = f'''<!doctype html><html lang="uk"><head><meta charset="utf-8"><title>Шпаргалка ведучому</title><style>
@page{{size:A4;margin:9mm 10mm}}*{{box-sizing:border-box}}body{{margin:0;font-family:'DejaVu Sans',Arial,sans-serif;font-size:8.6pt;color:#1d2125}}
.top{{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:2.5px solid #1f6b44;padding-bottom:4px;margin-bottom:5px}}
h1{{margin:0;font-size:14pt}}.leg{{font-size:8.2pt;color:#444}}
table{{width:100%;border-collapse:collapse}}th,td{{border:1px solid #d3d8de;padding:1.2mm 1.6mm;vertical-align:top;text-align:left}}th{{background:#1f6b44;color:#fff;font-size:8.2pt}}
td:first-child{{width:9mm;text-align:center;color:#666}}td:nth-child(2){{width:33mm}}td.t{{width:13mm;text-align:center;font-weight:700}}td:nth-child(4){{width:24mm;font-size:8pt}}
tr.m td{{background:#eef6f0}}tr.s td{{color:#444}}
.two{{display:grid;grid-template-columns:1fr 1fr;gap:5mm;margin-top:5px}}h2{{font-size:10pt;margin:4px 0 3px;color:#1f6b44}}ul{{margin:0;padding-left:5mm}}li{{margin:1px 0}}
.box{{border:1px solid #d3d8de;border-radius:2mm;padding:2mm 3mm}}
</style></head><body>
<div class="top"><div><h1>Кераміка України — шпаргалка ведучому</h1><div class="leg">⏱ — закінчити до (хв:с) · ⭐ головне, можна довше · ⚡ коротко, 30 с · ❓ питання до залу · ✋ дія</div></div><div class="leg">вишкіл · до 20 хв</div></div>
<table><tr><th>№</th><th>Слайд</th><th>⏱</th><th>✋</th><th>Що сказати / запитати</th></tr>{rows}</table>
<div class="two"><div class="box"><h2>Відповіді вікторини на карті</h2><ul>{qz}</ul></div>
<div class="box"><h2>Аркуш учасника — номери країв</h2><p style="margin:0 0 3px">{ARK}</p><h2>Крапля води</h2><p style="margin:0">вазон — вбирається · печатка — не вбирається (крапля лежить) · піала — скочується</p></div></div>
<div class="two"><div class="box"><h2>Перед початком</h2><ul><li>Відкрити гутірку на ноутбуці, увімкнути «Пульт», відсканувати QR.</li><li>Зразки на столі: форма, піала, вазон, печатка, вода.</li><li>6 аркушів і ручки.</li></ul></div>
<div class="box"><h2>Якщо пульт не працює</h2><ul><li>Гортати ← → на ноутбуці, краї — мишкою.</li><li>Ця шпаргалка — замість підказок.</li></ul></div></div>
</body></html>'''
open(OUT, 'w', encoding='utf8').write(html); print('ok')
